		label={[right, xshift=2pt, yshift=-2pt]:{\small $B(1,2)$}}] at (A) {};
	\node[circle, fill=\mypointcolor, draw=none, inner sep=1.5pt, 
		label={[above, yshift=0pt]:{\small $D(1,3)$}}] at (B) {};

\end{axis}
